async function startRun(){if(status==='starting'||status==='countdown')return;config=currentSetup();if(!['type','voice'].includes(config.control)){setupError('Choose Type or Speak.');return}if(['ipa','letters'].includes(config.skill)&&config.control!=='voice'){setupError('Letters and IPA cards use Speak mode.');return}if(config.control==='voice'&&!InkVoice.VoiceController.supported()){setupError('This browser does not support Speak mode. Choose Type.');return}const runPool=InkContent.poolFor(config,custom);if(!runPool.length||(config.personalOnly&&runPool.length<2)){setupError('Add at least two suitable targets, or turn off “Only my saved lists” in Fine-tune.');return}const token=++runToken;status='starting';$('startBtn').disabled=true;gameAudio.stop();gameAudio.prepare();gameAudio.configure({...config,voice:config.control==='voice'});$('pauseMusic').checked=config.music;$('pauseEffects').checked=config.sound;$('setupStatus').className='setup-status';$('setupStatus').textContent=config.control==='voice'?'Allow the microphone request to start speaking.':'Opening the gates…';persistentError='';stopInputs();try{if(config.control==='voice')await voice.start(config.accent);if(token!==runToken)return;voiceLedgers.clear();elements.clear();$('enemyLayer').replaceChildren();$('spellLayer').replaceChildren();$('liveAnswer').value='';answerReset.edit();$('powerEffects').hidden=true;$('arena').classList.remove('frozen','slowed','iced');$('bossBar').hidden=true;$('dropLayer').replaceChildren();dropElements.clear();pickScene();$('manaCount').textContent='0 / 10';$('manaFill').style.width='0%';document.querySelectorAll('[data-skill]').forEach(b=>{b.disabled=true;b.classList.remove('charged')});clearTimeout(noticeTimer);$('battleNotice').classList.remove('show');$('battleNotice').textContent='';$('pauseOverlay').hidden=true;$('gameView').classList.remove('is-paused');$('comboBadge').hidden=true;$('countdownOverlay').hidden=false;$('arenaHint').classList.remove('faded');$('arenaHint').innerHTML=config.control==='type'?'TYPE TO STRIKE.<small>Type anywhere in this game tab.</small>':'SAY IT. SLAY IT.<small>Say one or several visible targets.</small>';$('typingBar').hidden=config.control!=='type';$('voiceTranscript').hidden=config.control!=='voice';$('voiceTranscript').textContent='Browser heard: —';$('inputIcon').textContent=config.control==='type'?'⌨':'◉';$('inputHelp').textContent=config.control==='type'?'TYPE ANYWHERE · AUTO FIRE':'STABLE SPEECH FIRES EARLY · MULTIPLE ANSWERS WELCOME';$('runTag').textContent=`${skillNames[config.skill].toUpperCase()} / ${config.control.toUpperCase()}`;$('paceTag').textContent=SPEEDS[config.speed].name.toUpperCase();configureKeyboard();$('liveAnswer').placeholder=config.skill==='numbers'?'Digits only, e.g. 98…':'Type the answer…';sound=config.sound;showPage('game');status='countdown';$('pauseBtn').disabled=true;$('gameScore').textContent='0000';$('gameHearts').textContent='♥♥♡♡♡';$('gameHearts').setAttribute('aria-label','2 hearts');$('waveLabel').textContent='WAVE 01';$('gameTime').textContent=config.duration?formatTime(config.duration):'∞';setReading(config.control==='voice'?'Mic ready. Say a target when it appears.':'Your answer finds its target.');for(const step of ['READY','GO']){if(token!==runToken)return;$('countdownText').textContent=step;$('countdownNote').textContent=step==='GO'?'HOLD THE LINE.':'READY TO HOLD THE LINE?';await new Promise(resolve=>setTimeout(resolve,step==='GO'?250:450));}if(token!==runToken)return;engine=new SurvivalEngine({pool:runPool,progressive:config.progressive,speed:config.speed,control:config.control,duration:config.duration,onEvent:handleEvent});engine.voiceReady=config.control!=='voice'||voice.ready;status='playing';gameKeyboard.setDisabled(false);gameAudio.start({...config,travel:engine.speed.travel,voice:config.control==='voice'});updateSpacing();$('countdownOverlay').hidden=true;$('pauseBtn').disabled=false;if(config.control==='type'&&!gameKeysActive)$('liveAnswer').focus({preventScroll:true});updateHUD();lastFrame=performance.now();cancelAnimationFrame(frameId);frameId=requestAnimationFrame(frame);saveLocal('inkfang-last-setup',config);if(document.hidden)pauseGame('The tab was hidden. Your run is safe.');}catch(err){if(token!==runToken)return;stopInputs();status='setup';showPage('setup');setupError(err.message);}finally{$('startBtn').disabled=false;}}
const SCENES=['graveyard','forest','library','harbour','cavern'];let lastScene='';
function pickScene(){const options=SCENES.filter(s=>s!==lastScene);lastScene=options[Math.floor(Math.random()*options.length)];$('arena').dataset.scene=lastScene;$('arenaScene').setAttribute('href','#scene-'+lastScene);}
function configureKeyboard(){const touch=(navigator.maxTouchPoints||0)>0||window.matchMedia('(pointer: coarse)').matches;gameKeysActive=InkKeyboard.usesGameKeys(config,{touch});const input=$('liveAnswer');input.readOnly=gameKeysActive;input.inputMode=gameKeysActive?'none':config.skill==='numbers'?'numeric':'text';$('gameView').classList.toggle('using-game-keys',gameKeysActive);gameKeyboard.setDisabled(true);gameKeyboard.configure({enabled:gameKeysActive,skill:config.skill});if(gameKeysActive&&document.activeElement===input)input.blur();}
function handleGameKey(key,{physical=false}={}){if(status!=='playing'||config?.control!=='type'||!physical&&!gameKeysActive)return;if(key==='Enter'){clearTimeout(typeTimer);answerReset.edit();handleAnswer($('liveAnswer').value,'type');return}const input=$('liveAnswer'),value=InkKeyboard.editValue(input.value,key,physical?'mixed':config.skill);if(value===input.value)return;input.value=value;processTyping();}
document.addEventListener('keydown',e=>{const target=e.target,input=$('liveAnswer'),editable=!!(target.isContentEditable||target.closest?.('textarea,select,[contenteditable="true"]')||target.tagName==='INPUT'&&target!==input);const route=InkTyping.routePhysicalKey({active:status==='playing'&&config?.control==='type',composing:e.isComposing,shortcut:e.ctrlKey||e.metaKey||e.altKey,nativeAnswer:target===input&&!gameKeysActive,otherEditable:editable,onButton:!!target.closest?.('button'),key:e.key,prevented:e.defaultPrevented});if(route){e.preventDefault();handleGameKey(e.key,{physical:true})}});

function setupError(message){$('setupStatus').textContent=message;$('setupStatus').className='setup-status error';status='setup';}
function frame(now){if(status==='playing'&&engine){const dt=Math.min((now-lastFrame)/1000,.1);engine.update(dt);renderPositions();updateHUD();if(engine.elapsed>2)$('arenaHint').classList.add('faded');}lastFrame=now;if(['playing','paused'].includes(status))frameId=requestAnimationFrame(frame);}
function updateSpacing(){if(!engine)return;engine.setArenaHeight($('arena').clientHeight);const heights=[...elements.values()].filter(el=>!el.classList.contains('boss-enemy')).map(el=>el.offsetHeight);const needed=(Math.max(90,...heights)+14)/arenaMetrics().span;engine.spacing=Math.max(engine.baseSpacing,Math.min(1.25,needed));}
// A boss leans away from a lane monster that is level with it, so the passing monster covers less of the boss's sign.
function bossShift(boss){if(!engine)return .5;const near=new Set(engine.enemies.filter(e=>!e.boss&&Math.abs(e.y-boss.y)<engine.spacing*.9).map(e=>e.lane));return near.size===1?(near.has(0)?.65:.35):.5}
const laneX=e=>(e.boss?bossShift(e):e.lane===1?.75:.25)+(e.sway||0);
// Arena geometry: monsters run from `top` to the finish line. Phones get a smaller frame and a lower line.
function arenaMetrics(){const h=$('arena').clientHeight,compact=window.matchMedia('(max-height:780px)').matches||window.matchMedia('(max-width:430px)').matches;const top=compact?52:76,bottom=compact?60:92;return{h,top,span:Math.max(110,h-top-bottom)}}
const yPx=(y,m=arenaMetrics())=>m.top+y*m.span;
const dropElements=new Map();
function renderDrops(m){const h=m;for(const d of engine.drops){let el=dropElements.get(d.id);if(!el){el=document.createElementNS('http://www.w3.org/2000/svg','svg');el.setAttribute('viewBox','0 0 40 48');el.setAttribute('class','drop');el.dataset.kind=d.kind;const use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href','#drop-'+d.kind);el.append(use);dropElements.set(d.id,el);$('dropLayer').append(el)}el.style.top=yPx(d.y,h)+'px';el.style.left=((d.lane===1?.75:.25)+d.sway)*100+'%';}}
function renderPositions(){const m=arenaMetrics();renderDrops(m);for(const e of engine.enemies){const el=elements.get(e.id);if(!el)continue;el.style.top=yPx(e.y,m)+'px';const left=laneX(e)*100+'%';if(el.style.left!==left)el.style.left=left;el.classList.toggle('lane-one',e.lane===1);}}
function updateEnemy(e){const el=elements.get(e.id);if(!el)return;el.dataset.kind=e.q.kind;el.dataset.monster=e.type;const label=el.querySelector('.target-label');label.textContent=e.q.display||e.q.prompt;label.setAttribute('aria-label',`Target: ${label.textContent}. ${e.name}, ${e.hp} hit${e.hp===1?'':'s'} remaining.`);const n=label.textContent.length;label.dataset.size=n<=12?'s':n<=28?'m':n<=50?'l':'xl';label.classList.toggle('long-target',n>55);el.querySelector('.enemy-hp i').style.width=(Math.max(0,e.hp-e.damage)/e.maxHp*100)+'%';el.querySelector('.enemy-meta').textContent=e.maxHp>1?`${e.name} · ${e.hp}/${e.maxHp}`:`${e.type==='healer'?'♥ ':''}${e.name}`;el.querySelector('.damage-hint').textContent='';}
function addEnemy(e){const archetype=InkEngine.MONSTERS[e.type];const el=document.createElement('div');el.className='enemy'+(e.lane===1?' lane-one':'')+(e.boss?' boss-enemy':'');el.dataset.kind=e.q.kind;el.dataset.monster=e.type;el.style.color=archetype.color;el.style.left=laneX(e)*100+'%';
const sprite=(id,cls,box)=>{const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox',box);svg.setAttribute('aria-hidden','true');svg.setAttribute('class',cls);const use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href','#'+id);svg.append(use);return svg};
const body=sprite(archetype.symbol,'enemy-body',e.boss?'0 0 220 170':'0 0 160 140');
const sign=document.createElement('div');sign.className='enemy-sign';const target=document.createElement('span');target.className='target-label';sign.append(sprite('ink-paw','paw left','0 0 48 44'),sprite('ink-paw','paw right','0 0 48 44'),target);
const hp=document.createElement('div');hp.className='enemy-hp';hp.append(document.createElement('i'));const meta=document.createElement('span');meta.className='enemy-meta';const hint=document.createElement('span');hint.className='damage-hint';const flame=sprite('drop-fire','burn-flame','0 0 40 48');
el.append(body,sign,hp,meta,hint,flame);elements.set(e.id,el);$('enemyLayer').append(el);updateEnemy(e);queueMicrotask(updateSpacing);
if(e.boss){battleNotice(`${e.name.toUpperCase()} · ${e.hp} ANSWERS`,'boss');showBossBar(e);gameAudio.effect('boss');gameAudio.setBoss(archetype.theme)}}
function showBossBar(e){const bar=$('bossBar');bar.hidden=false;bar.dataset.theme=InkEngine.MONSTERS[e.type].theme;$('bossBarIcon').setAttribute('href','#'+InkEngine.MONSTERS[e.type].symbol);$('bossBarName').textContent=e.name.toUpperCase();updateBossBar(e);}
function updateBossBar(e){if(!e){$('bossBar').hidden=true;return}$('bossBarFill').style.width=(e.hp/e.maxHp*100)+'%';$('bossBarHits').textContent=e.hp;}
let noticeTimer=null;
function battleNotice(text,kind=''){clearTimeout(noticeTimer);const n=$('battleNotice');n.textContent=text;n.classList.toggle('boss-notice',kind==='boss');n.classList.add('show');noticeTimer=setTimeout(()=>n.classList.remove('show'),kind==='boss'?3200:2400);}
function handleEvent(event){
 if(event.type==='spawn'){addEnemy(event.enemy);if(status==='playing')gameAudio.effect('spawn');return}
 if(event.type==='hit'||event.type==='boss-damage'){updateEnemy(event.enemy);const el=elements.get(event.enemy.id);el?.classList.remove('damaged');if(el){void el.offsetWidth;el.classList.add('damaged')}spellAt(event.enemy,event.type==='boss-damage'?`−${event.damage} HP`:event.damage===2?'DOUBLE HIT':'HIT');if(event.enemy.boss){updateBossBar(event.enemy);$('bossBar').classList.remove('boss-hurt');void $('bossBar').offsetWidth;$('bossBar').classList.add('boss-hurt')}gameAudio.effect('chip');queueMicrotask(updateSpacing);return}
 if(event.type==='drop'){gameAudio.effect('drop');return}
 if(event.type==='collect'){const el=dropElements.get(event.drop.id);if(el){el.classList.add('collected');setTimeout(()=>el.remove(),450);dropElements.delete(event.drop.id)}if(event.drop.kind==='ice'){battleNotice('❄ FROST ORB · SWARM SLOWED');gameAudio.effect('ice')}else{battleNotice('🔥 EMBER ORB · MONSTERS BURN');gameAudio.effect('fire')}return}
 if(event.type==='burn'){updateEnemy(event.enemy);const el=elements.get(event.enemy.id);if(el){el.classList.remove('damaged');void el.offsetWidth;el.classList.add('damaged')}if(event.enemy.boss)updateBossBar(event.enemy);spellAt(event.enemy,'BURN');gameAudio.effect('chip');return}
 if(event.type==='swerve'){const el=elements.get(event.enemy.id);if(el){el.classList.remove('swerving');void el.offsetWidth;el.classList.add('swerving');setTimeout(()=>el.classList.remove('swerving'),500)}return}
 if(event.type==='mana-ready'){battleNotice(event.skill==='nova'?'MANA FULL · INKSTORM READY':'SLOWFIELD READY · TAP ◴');return}
 if(event.type==='skill'){battleNotice(InkEngine.SKILLS[event.skill].name.toUpperCase()+' READY');gameAudio.effect(event.skill);return}
 if(event.type==='chain'){chainAt(event.from,event.to);gameAudio.effect('chain');return}
 if(event.type==='heart'){battleNotice(event.gained?'♥ +1 HEART':'♥ HEARTS FULL');gameAudio.effect('heart');return}
 if(event.type==='nova'){battleNotice('INKSTORM!');const blast=document.createElement('div');blast.className='nova-wave';$('spellLayer').append(blast);setTimeout(()=>blast.remove(),1000);gameAudio.effect('nova');return}
 if(event.type==='kill'){const el=elements.get(event.enemy.id);if(el){el.classList.add('dying');setTimeout(()=>el.remove(),300);elements.delete(event.enemy.id)}spellAt(event.enemy,`+${event.points}`);if(!event.spell)gameAudio.effect(engine.combo>=3?'combo':'hit',engine.combo);if(event.enemy.boss){battleNotice(`${event.enemy.name.toUpperCase()} DEFEATED!`,'boss');updateBossBar(null);gameAudio.setBoss(null)}return}
 if(event.type==='partial'){const el=elements.get(event.enemy.id);if(el){el.querySelector('.enemy-hp i').style.width=((event.enemy.hp-event.enemy.damage)/event.enemy.maxHp*100)+'%';el.querySelector('.damage-hint').textContent=[...norm(event.enemy.q.answer)].map((c,i)=>event.enemy.locked.has(i)?c:'_').join(' ');el.classList.remove('damaged');void el.offsetWidth;el.classList.add('damaged')}spellAt(event.enemy,'HIT');gameAudio.effect('chip');return}
 if(event.type==='escape'){const el=elements.get(event.enemy.id);el?.remove();elements.delete(event.enemy.id);if(event.enemy.boss){updateBossBar(null);gameAudio.setBoss(null)}$('arena').classList.remove('hurt');void $('arena').offsetWidth;$('arena').classList.add('hurt');setReading(`Escaped: ${event.enemy.q.display} → ${event.enemy.q.answer}`,'warning');gameAudio.effect('escape');return}
 if(event.type==='end')finishRun(event.reason);
}
function spellAt(e,label){const layer=$('spellLayer'),w=$('arena').clientWidth,h=$('arena').clientHeight,x=w*laneX(e),y=yPx(e.y),sx=w/2,sy=h-52,dx=x-sx,dy=y-sy;const splat=document.createElementNS('http://www.w3.org/2000/svg','svg');splat.setAttribute('viewBox','0 0 60 60');splat.setAttribute('class','hit-splat'+(e.boss?' boss-splat':''));const use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href','#ink-splat');splat.append(use);splat.style.left=x+'px';splat.style.top=y+'px';const beam=document.createElement('div');beam.className='hit-beam';beam.style.left=sx+'px';beam.style.top=sy+'px';beam.style.width=Math.hypot(dx,dy)+'px';beam.style.transform=`rotate(${Math.atan2(dy,dx)}rad)`;const pop=document.createElement('div');pop.className='hit-pop';pop.textContent=label;pop.style.left=x-15+'px';pop.style.top=y-46+'px';layer.append(beam,splat,pop);setTimeout(()=>{beam.remove();splat.remove();pop.remove()},800);}
function handleAnswer(value,source){if(status!=='playing'||!engine)return;const result=engine.submit(value,{partial:source!=='voice'});if(['kill','hit'].includes(result.type)){setReading(`${value} ✓ · ${result.type==='hit'?`${result.enemy.name}: ${result.enemy.hp} left. New target!`:'Target down!'}`,'success');if(source==='type'){answerReset.cancel();$('liveAnswer').value=''}}else if(result.type==='partial'){setReading(`${value} · Partial hit. Complete the answer.`,'success');if(source==='type')answerReset.arm()}else{setReading(`Read: ${value} · No match yet. Try again.`,'warning');if(source==='type')answerReset.arm()}$('arenaHint').classList.add('faded');updateHUD();}
function handleSpeech(alternatives,meta={utterance:'legacy',final:true,stable:true}){if(status!=='playing'||!engine)return;let ledger=voiceLedgers.get(meta.utterance);if(!ledger){ledger=new SpeechLedger();voiceLedgers.set(meta.utterance,ledger);if(voiceLedgers.size>40)voiceLedgers.delete(voiceLedgers.keys().next().value)}let best=[];for(const transcript of alternatives){const matches=ledger.peek(transcript,engine.enemies,numberToWords,{...meta,lettersOnly:config.skill==='letters'});if(matches.length>best.length)best=matches;}if(best.length){ledger.commit(best);let hits=0;for(const match of best){if(!engine.enemies.some(e=>e.id===match.id))continue;const result=engine.submit(match.answer,{partial:false,targetId:match.id,targetRevision:match.revision});if(['kill','hit'].includes(result.type))hits++;}if(hits)setReading(`${best.map(m=>m.answer).join(' · ')} → ${hits} spell hit${hits===1?'':'s'}!`,'success');updateHUD();return}if(meta.final&&!ledger.consumed.size)setReading(`Heard “${alternatives[0]||''}” · No target matched. Try again.`,'warning');}
function formatTime(seconds){seconds=Math.max(0,Math.ceil(seconds));return`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
function updateHUD(){if(!engine)return;gameAudio.setWave(engine.wave);gameAudio.setPace(engine.travel/engine.multiplier);$('gameScore').textContent=String(engine.score).padStart(4,'0');$('waveLabel').textContent=`W${String(engine.wave).padStart(2,'0')} · LV ${engine.level}`;$('gameTime').textContent=config.duration?formatTime(config.duration-engine.elapsed):formatTime(engine.elapsed);$('gameHearts').textContent='♥'.repeat(Math.max(0,engine.lives))+'♡'.repeat(5-Math.max(0,engine.lives));$('gameHearts').setAttribute('aria-label',`${engine.lives} hearts`);$('manaCount').textContent=`${engine.mana} / ${engine.maxMana}`;$('manaFill').style.width=engine.mana/engine.maxMana*100+'%';document.querySelectorAll('[data-skill]').forEach(b=>{b.disabled=status!=='playing'||!engine.skillReady(b.dataset.skill);b.classList.toggle('charged',!b.disabled)});const effects=[];if(engine.elapsed<engine.freezeUntil)effects.push(`❄ Frozen ${Math.ceil(engine.freezeUntil-engine.elapsed)}s`);else if(engine.elapsed<engine.slowUntil)effects.push(`◴ Slow ${Math.ceil(engine.slowUntil-engine.elapsed)}s`);if(engine.elapsed<engine.iceUntil)effects.push(`❄ Frost ${Math.ceil(engine.iceUntil-engine.elapsed)}s`);if(engine.doubleCharges)effects.push(`×2 · ${engine.doubleCharges} answers`);if(engine.chainCharges)effects.push(`ϟ · ${engine.chainCharges} answers`);$('powerEffects').hidden=!effects.length;$('powerEffects').textContent=effects.join(' · ');updateBossBar(engine.boss);$('arena').classList.toggle('iced',engine.elapsed<engine.iceUntil);for(const e of engine.enemies){const el=elements.get(e.id);if(el)el.classList.toggle('burning',!!e.burnTicks)}$('arena').classList.toggle('frozen',engine.elapsed<engine.freezeUntil);$('arena').classList.toggle('slowed',engine.elapsed<engine.slowUntil);$('comboBadge').hidden=engine.combo<2;$('comboBadge').textContent=`${engine.combo}× COMBO`;}
function pauseGame(message='Your run is paused. Monsters wait here.'){message=t(message);if(status!=='playing')return;status='paused';$('gameView').classList.add('is-paused');gameKeyboard.setDisabled(true);document.querySelectorAll('[data-skill]').forEach(b=>b.disabled=true);stopInputs();gameAudio.pause();$('pauseTitle').innerHTML=persistentError?`${t('MIC NEEDS')}<br>${t('A MOMENT.')}`:`${t('SWARM')}<br>${t('ON HOLD.')}`;$('pauseNote').textContent=message;$('pauseOverlay').hidden=false;$('resumeBtn').disabled=false;}
async function resumeGame(){if(status!=='paused')return;$('resumeBtn').disabled=true;try{if(config.control==='voice')await voice.start(config.accent);persistentError='';$('pauseOverlay').hidden=true;$('gameView').classList.remove('is-paused');status='playing';updateSpacing();renderPositions();gameKeyboard.setDisabled(false);answerReset.edit();if($('liveAnswer').value)answerReset.arm();updateHUD();gameAudio.resume();lastFrame=performance.now();if(config.control==='type'&&!gameKeysActive)$('liveAnswer').focus({preventScroll:true});setReading(config.control==='voice'?'Mic on · Say a target.':'Back in the fight.');}catch(err){$('pauseNote').textContent=err.message}finally{$('resumeBtn').disabled=false;}}
function returnSetup(){runToken++;stopInputs();gameAudio.stop();cancelAnimationFrame(frameId);status='setup';engine=null;voiceLedgers.clear();elements.clear();$('enemyLayer').replaceChildren();$('countdownOverlay').hidden=true;$('pauseOverlay').hidden=true;if($('summaryDialog').open)$('summaryDialog').close();showPage('setup');setupChanges();$('setupStatus').className='setup-status';$('setupStatus').textContent=t('Change your setup. Then take another shot.');window.InkGuide?.refresh(true);}
function finishRun(reason){gameKeyboard.setDisabled(true);document.querySelectorAll('[data-skill]').forEach(b=>b.disabled=true);if(status==='ended')return;status='ended';stopInputs();gameAudio.stop();gameAudio.effect(reason==='time'?'win':'end');cancelAnimationFrame(frameId);$('resultEyebrow').textContent=t(reason==='time'?'LINE HELD. WELL PLAYED.':'THE SWARM GOT THROUGH. YOUR MAGIC GOT STRONGER.');$('resultTitle').innerHTML=reason==='time'?`${t('YOU HELD')}<br>${t('THE LINE.')}`:`${t('YOU MADE')}<br>${t('YOUR MARK.')}`;const badge=InkOnboarding.badgeFor(engine);$('resultBadge').textContent=t(badge.name);$('resultRank').textContent=badge.glyph;$('summaryDialog').dataset.badge=badge.glyph;$('resultScore').textContent=engine.score;$('resultKills').textContent=engine.kills;$('resultCombo').textContent=engine.bestCombo;$('resultTime').textContent=formatTime(engine.elapsed);const bestKey=`inkfang-v5-best-${config.skill}-${config.control}-${config.speed}-${config.range}-${config.duration}`;const previous=readLocal(bestKey,0);const isBest=engine.score>previous;if(isBest)saveLocal(bestKey,engine.score);$('newBest').hidden=!isBest;$('resultBest').textContent=t('Your best: {n}',{n:Math.max(previous,engine.score)});$('resultDetails').textContent=`${t(skillNames[config.skill])} · ${t(config.control==='voice'?'Speak':'Type')} · ${t(SPEEDS[config.speed].name)} · ${t(engine.bossKills===1?'Wave {w} · {b} boss defeated':'Wave {w} · {b} bosses defeated',{w:engine.wave,b:engine.bossKills})}`;$('milestoneLabel').textContent=t(engine.kills>=50?'Legendary run. Keep going.':'Your next badge');$('milestoneCount').textContent=t('{k} / {g} monsters',{k:engine.kills,g:badge.goal});$('milestoneFill').style.width=Math.min(100,engine.kills/badge.goal*100)+'%';const review=$('reviewList');review.replaceChildren();const unique=[...new Map(engine.review.map(q=>[q.id,q])).values()];$('reviewTitle').textContent=unique.length?t(unique.length===1?'Revisit {n} target →':'Revisit {n} targets →',{n:unique.length}):t('A clean run. Every target handled. ✓');document.querySelector('.results-review').open=false;if(unique.length){for(const q of unique.slice(0,16)){const row=document.createElement('div');row.className='review-target';const clue=document.createElement('span'),answer=document.createElement('strong'),outcome=document.createElement('small');clue.textContent=q.prompt;answer.textContent=q.answer;outcome.textContent=t(q.outcome==='escaped'?'Escaped · Try it again':'Recovered after a partial hit');row.append(clue,answer,outcome);review.append(row)}}else review.textContent=t('Try a faster pace or a bigger number range.');$('summaryDialog').showModal();}
$('setupForm').onsubmit=e=>{e.preventDefault();startRun()};$('pauseBtn').onclick=()=>pauseGame();$('resumeBtn').onclick=resumeGame;$('exitBtn').onclick=returnSetup;$('retryBtn').onclick=()=>{$('summaryDialog').close();status='setup';startRun()};$('setupBtn').onclick=returnSetup;$('summaryDialog').oncancel=e=>{e.preventDefault();returnSetup()};function processTyping(e){clearTimeout(typeTimer);answerReset.edit();if(status!=='playing'||config?.control!=='type')return;if(e?.isComposing){setReading('Switch to an English keyboard and turn off UniKey / Vietnamese input for instant typing.','warning');return;}const input=$('liveAnswer');input.value=input.value.toUpperCase().slice(0,24);const value=input.value,plan=typingPlan(value,engine.enemies);if(plan.delay===0){handleAnswer(value,'type');return}if(plan.delay===null)return;const activeRun=runToken;typeTimer=setTimeout(()=>{if(activeRun===runToken&&status==='playing'&&input.value===value)handleAnswer(value,'type')},plan.delay);}$('liveAnswer').oncompositionstart=()=>{clearTimeout(typeTimer);answerReset.edit();if(status==='playing')setReading('Switch to an English keyboard and turn off UniKey / Vietnamese input for instant typing.','warning')};$('liveAnswer').oninput=processTyping;$('liveAnswer').oncompositionend=processTyping;$('liveAnswer').onkeydown=e=>{if(gameKeysActive)return;if(e.key==='Enter'&&!e.isComposing){e.preventDefault();clearTimeout(typeTimer);answerReset.edit();handleAnswer(e.target.value,'type')}};
$('gameSound').onclick=()=>{if(status==='playing')pauseGame('Adjust your soundtrack and effects. Resume when you’re ready.');$('pauseMusic').focus()};$('pauseMusic').onchange=e=>{config.music=e.target.checked;document.querySelector('[name=music]').checked=config.music;gameAudio.setMusic(config.music);saveLocal('inkfang-last-setup',config)};$('pauseEffects').onchange=e=>{config.sound=e.target.checked;document.querySelector('[name=sound]').checked=config.sound;gameAudio.setEffects(config.sound);saveLocal('inkfang-last-setup',config)};$('musicVolume').oninput=e=>gameAudio.setVolume(Number(e.target.value)/100);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')){if(status==='playing')pauseGame();else if(status==='paused')resumeGame()}});document.addEventListener('visibilitychange',()=>{if(document.hidden){if(status==='playing')pauseGame('The tab was hidden. Your run is paused.');else gameAudio.stop();}});window.addEventListener('pagehide',()=>{voice.stop();gameAudio.stop()});window.addEventListener('blur',()=>{if(status==='playing')pauseGame('The game lost focus. Your run is paused.');});
function viewport(){const vv=window.visualViewport;document.documentElement.style.setProperty('--play-height',(vv?.height||window.innerHeight)+'px');document.documentElement.style.setProperty('--play-top',(vv?.offsetTop||0)+'px');if(engine&&status==='playing'){updateSpacing();renderPositions();}}window.visualViewport?.addEventListener('resize',viewport);window.visualViewport?.addEventListener('scroll',viewport);window.addEventListener('resize',viewport);viewport();
$('homeNav').onclick=()=>{if(status==='playing')pauseGame();showPage('setup')};$('bankNav').onclick=()=>{gameAudio.stop();showPage('bank')};$('helpBtn').onclick=()=>{stopMicCheck();gameAudio.stop();$('helpDialog').showModal()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
function teacherBank(){const base={control:'voice',range:1000,level:3};return[...InkContent.poolFor({...base,skill:'mixed'},custom),...InkContent.poolFor({...base,skill:'spelling'},custom),...InkContent.IPA,...custom.filter(q=>q.mode==='numbers').map(q=>({...q,kind:'numbers'}))];}
let bankPage=0;const PAGE_SIZE=16;
function filteredBank(){const search=$('bankSearch').value.toLowerCase(),kind=choiceValue('bankFilter');return teacherBank().filter(q=>(kind==='all'||q.kind===kind)&&[q.prompt,q.answer,q.topic].join(' ').toLowerCase().includes(search));}
function renderBank(){$('exportPersonal').disabled=!custom.length;const rows=filteredBank();bankPage=Math.max(0,Math.min(bankPage,Math.ceil(rows.length/PAGE_SIZE)-1));$('bankBody').replaceChildren(...rows.slice(bankPage*PAGE_SIZE,(bankPage+1)*PAGE_SIZE).map(q=>{const tr=document.createElement('tr');for(const text of [q.prompt,[q.answer,...(q.acceptedAnswers||[])].join(' / '),skillNames[q.kind]||skillNames[q.mode]||q.kind]){const td=document.createElement('td');td.textContent=text;tr.append(td)}return tr}));$('bankResults').textContent=rows.length?`${bankPage*PAGE_SIZE+1}–${Math.min((bankPage+1)*PAGE_SIZE,rows.length)} of ${rows.length} targets`:'No matching targets.';$('prevPage').disabled=bankPage===0;$('nextPage').disabled=(bankPage+1)*PAGE_SIZE>=rows.length;}
$('bankSearch').oninput=()=>{bankPage=0;renderBank()};$('bankSkill').onchange=()=>{bankPage=0;renderBank()};$('prevPage').onclick=()=>{bankPage--;renderBank()};$('nextPage').onclick=()=>{bankPage++;renderBank()};
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}$('exportBank').onclick=()=>download(JSON.stringify(teacherBank(),null,2),'inkfang-question-bank.json','application/json');$('exportCsv').onclick=()=>{const columns=['id','kind','mode','level','prompt','answer','acceptedAnswers','spoken','topic'];const rows=[columns.join(','),...teacherBank().map(q=>columns.map(k=>'"'+String(q[k]??'').replaceAll('"','""')+'"').join(','))];download('\uFEFF'+rows.join('\r\n'),'inkfang-question-bank.csv','text/csv;charset=utf-8')};$('exportPersonal').onclick=()=>download(JSON.stringify(custom,null,2),'inkfang-my-lists.json','application/json');
$('customForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),q=normalizeQuestion({mode:f.get('mode'),prompt:f.get('prompt')||'',answer:f.get('answer'),acceptedAnswers:String(f.get('acceptedAnswers')||'').split(/[,;]/).filter(x=>x.trim()),level:Number(f.get('level'))});if(!q){$('bankNotice').textContent='Use a valid English answer and clue, or a whole number from 0 to 1000.';return}custom.push({...q,id:`custom-${Date.now()}`});const saved=saveLocal('ra-custom',custom);renderBank();e.target.reset();updateCustomForm();$('bankNotice').textContent=saved?'Added. Select Only my saved lists to practise your imports.':'Added for this session. Browser storage is unavailable.';};
function updateCustomForm(){const form=$('customForm'),mode=new FormData(form).get('mode');form.elements.prompt.required=mode==='vocabulary';form.elements.prompt.placeholder=mode==='vocabulary'?'Write a short, accurate clue.':'Optional · generated from the answer';form.elements.answer.inputMode=mode==='numbers'?'numeric':'text';}
$('customForm').addEventListener('change',updateCustomForm);updateCustomForm();
$('removeCustom').onclick=()=>{if(!custom.length){$('bankNotice').textContent='No custom questions to remove.';return}if(!confirm(`Remove ${custom.length} custom questions from this browser? Export them first if you want a copy.`))return;custom=[];saveLocal('ra-custom',custom);renderBank();$('bankNotice').textContent='Custom questions removed.';};
function addImported(questions){const known=new Set(custom.map(q=>[q.mode,q.prompt,q.answer].join('|')));let added=0;for(const q of questions){const key=[q.mode,q.prompt,q.answer].join('|');if(!known.has(key)){custom.push({...q,id:q.id||`import-${Date.now()}-${added}`});known.add(key);added++}}return added;}
$('importBank').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('Please use a JSON file smaller than 2 MB.');const result=parseJSONList(await file.text());if(!result.questions.length)throw Error(result.errors.slice(0,2).join(' ')||'The list is empty.');const added=addImported(result.questions),saved=saveLocal('ra-custom',custom);renderBank();$('bankNotice').textContent=`${added} added; ${result.errors.length} unsupported items skipped.${saved?'':' Browser storage unavailable.'} Select Only my saved lists in Play to use them.`;}catch(err){$('bankNotice').textContent=err.message}e.target.value='';};

