document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{if(status!=='playing'||!engine)return;if(b.dataset.skill==='nova'){castInkstorm();return}const result=engine.castSkill(b.dataset.skill);if(result.type==='skill'){setReading(`${InkEngine.SKILLS[b.dataset.skill].name} activated.`,'success');updateHUD()}});
