$('copyChatbotPrompt').onclick=async()=>{try{await navigator.clipboard.writeText($('chatbotPrompt').value);$('promptCopyStatus').textContent='Prompt copied. Paste it into your chatbot, then replace the three placeholders.';}catch{$('chatbotPrompt').focus();$('chatbotPrompt').select();$('promptCopyStatus').textContent='Select Copy on your device, or press Ctrl+C / Command+C to copy the highlighted prompt.';}};
$('useWordList').onclick=()=>{const result=parsePracticeList($('wordListText').value,choiceValue('pasteLevel'));if(result.errors.length){$('wordListStatus').textContent=result.errors.slice(0,3).join(' ');return}if(!result.questions.length){$('wordListStatus').textContent='Paste at least two targets to begin.';return}const added=addImported(result.questions),saved=saveLocal('ra-custom',custom);$('wordListDialog').close();setChoice('skill',skillForList(result.questions),$('setupForm'));document.querySelector('[name=personalOnly]').checked=true;saveLocal('inkfang-last-setup',currentSetup());showPage('setup');setupChanges();window.InkGuide?.refresh(true);$('setupStatus').textContent=`${added} targets added. Your saved list is selected.${saved?'':' Saved for this session only.'} Press Play to begin.`;};

function chainAt(from,to){const w=$('arena').clientWidth,h=$('arena').clientHeight;const point=e=>({x:w*laneX(e),y:yPx(e.y)});const a=point(from),b=point(to),bolt=document.createElement('div');bolt.className='chain-bolt';bolt.style.left=a.x+'px';bolt.style.top=a.y+'px';bolt.style.width=Math.hypot(b.x-a.x,b.y-a.y)+'px';bolt.style.transform=`rotate(${Math.atan2(b.y-a.y,b.x-a.x)}rad)`;$('spellLayer').append(bolt);setTimeout(()=>bolt.remove(),650);}
